<script setup lang="ts">
import { Head, useForm, router } from '@inertiajs/vue3'
defineProps<{quotas:{data:any[];total:number}}>()
const form=useForm({user_id:'',max_total_bytes:0,max_file_bytes:0,period:'lifetime'})
const bytes=(n:number)=>n>=1073741824?(n/1073741824).toFixed(2)+' GiB':n>=1048576?(n/1048576).toFixed(2)+' MiB':n+' B'
</script>
<template><Head title="مدیا و سهمیه‌ها"/><v-container fluid class="pa-6"><h1 class="text-h4 mb-5">مدیا و سهمیه‌ها</h1><v-row><v-col cols="12" md="4"><v-card rounded="xl" class="pa-5"><v-card-title>تعریف سهمیه کاربر</v-card-title><v-card-text><v-form @submit.prevent="form.post('/media/quotas')"><v-text-field v-model="form.user_id" label="شناسه Matrix کاربر"/><v-text-field v-model.number="form.max_total_bytes" type="number" label="حداکثر مصرف کل (bytes)"/><v-text-field v-model.number="form.max_file_bytes" type="number" label="حداکثر اندازه هر فایل (bytes)"/><v-select v-model="form.period" label="دوره محاسبه" :items="[{title:'بدون بازنشانی',value:'lifetime'},{title:'روزانه',value:'day'},{title:'هفتگی',value:'week'},{title:'ماهانه',value:'month'}]"/><v-btn type="submit" color="primary" block :loading="form.processing">ذخیره سهمیه</v-btn></v-form></v-card-text></v-card></v-col><v-col cols="12" md="8"><v-card rounded="xl" class="pa-5"><v-card-title>سهمیه‌های تعریف‌شده</v-card-title><v-list><v-list-item v-for="q in quotas.data" :key="q.user_id" :title="q.user_id" :subtitle="bytes(q.max_total_bytes)+' کل · '+bytes(q.max_file_bytes)+' هر فایل · '+q.period"><template #append><v-btn icon="mdi-delete" color="error" variant="text" @click="router.delete('/media/quotas/'+encodeURIComponent(q.user_id))"/></template></v-list-item></v-list><v-alert type="info" variant="tonal" class="mt-3">نمودار مصرف تجمیعی و درصد سهمیه در گام بعدی متصل می‌شود.</v-alert></v-card></v-card></v-col></v-row></v-container></template>
